def countSumGrids(rows, cols, rowSums, colSums):
    rs = list(rowSums)
    cs = list(colSums)

    def go(pos, used):
        if pos == rows * cols:
            return 1
        r, c = divmod(pos, cols)
        last_col = c == cols - 1
        last_row = r == rows - 1
        total = 0
        for d in range(1, 10):
            if (used >> d) & 1 or d > rs[r] or d > cs[c]:
                continue
            if last_col and d != rs[r]:
                continue
            if last_row and d != cs[c]:
                continue
            if not last_col and rs[r] - d <= 0:
                continue
            if not last_row and cs[c] - d <= 0:
                continue
            rs[r] -= d
            cs[c] -= d
            total += go(pos + 1, used | (1 << d))
            rs[r] += d
            cs[c] += d
        return total

    return go(0, 0)
